"""Aggregate measured pilot evidence; no invented thresholds or security proof."""
from pathlib import Path
import datetime,hashlib,json,platform,statistics
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'docs/evidence/devnet-gui-v1'
def summary(values):return dict(n=len(values),median=statistics.median(values),minimum=min(values),maximum=max(values),sample_stdev=statistics.stdev(values))
def main():
    assert not (OUT/'performance.json').exists() and not (OUT/'execution.json').exists()
    backend=json.loads((OUT/'accepted/backend.json').read_bytes());gui=json.loads((OUT/'gui.json').read_bytes());fresh=json.loads((OUT/'frontend-process.json').read_bytes())
    report=dict(result='MEASURED_BOUNDED_PILOT',tk_wsl_ready_warm_python_ms=summary([x['tk_and_wsl_ready_ms'] for x in gui['launch_trials']]),fresh_python_tk_wsl_start_ready_exit_ms=summary([x['process_start_ready_and_exit_ms'] for x in fresh['trials']]),review_sign_submit_refresh_ms=summary(gui['transaction_workflow_trials_ms']),gui_dispatch_added_ms=summary([x['added_dispatch_ms'] for x in gui['dispatch_trials']]),windows_unlocked_working_set_mib=summary([x['windows_working_set_bytes']/1048576 for x in gui['dispatch_trials']]),backend_unlocked_rss_mib=summary([x['backend_rss_kib']/1024 for x in gui['dispatch_trials']]),backend_pipe_full_refresh_ms=summary([x['pipe_refresh_ms'] for x in backend['metrics']['trials']]),direct_observe_without_persistence_ms=summary([x['direct_observe_ms'] for x in backend['metrics']['trials']]),notes=['Seven sequential trials per listed distribution; existing WSL distro running, no reboot cold-start claim.','Real transaction workflows exclude human deliberation and use disposable assets.','Fresh process measurement includes normal exit, so it is an upper bound for readiness, not time-to-visible-window.','Memory is sampled resident/working set, not allocator/KDF/RandomX peak or combined host/VM memory.','Pipe refresh includes full scan, Argon2 encrypted cache and journal publication; direct observe excludes persistence.','No speed advantage or performance acceptance gate invented. Historical Phase6A creation flag and provenance gap remain open.','GUI timing precedes final timer-cleanup and stale-history label refinements; focused lifecycle/display tests validate those final changes.'])
    (OUT/'performance.json').write_bytes(json.dumps(report,indent=2).encode()+b'\n')
    names=['accepted/backend.json','gui.json','frontend-process.json','helpers.json','lifecycle.json','stale-history.json','display.json','regressions/summary.json']
    checks={name:len(json.loads((OUT/name).read_bytes()).get('checks',[])) for name in names}
    record=dict(result='COMPLETE_DEVNET_PILOT_WITH_LIMITATIONS',observed_at_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),input_checkpoint='70202cbced73ab748f792c77137aa993655dd5c7',host_python=platform.python_version(),host_platform=platform.platform(),tk=gui['tk_version'],checks=checks,script_sha256={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in Path(__file__).parent.iterdir() if p.suffix in ('.py','.ps1')},evidence_sha256={p.relative_to(OUT).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in OUT.rglob('*.json') if p.name not in ('execution.json','audit.json')},full_gui_then_focused_final_changes=True,manual_gui_acceptance='PENDING',independent_security_review='PENDING',phase5='INCOMPLETE_WITH_BLOCKERS',phase6a='INCOMPLETE_WITH_BLOCKERS',route_c='PAUSED',r1='KILL',r2='NOT_STARTED',phase6b='NOT_STARTED',phase7='NOT_STARTED')
    (OUT/'execution.json').write_bytes(json.dumps(record,indent=2).encode()+b'\n');print(json.dumps(record['checks']))
